import React, { useState } from 'react';

const Footer = () => {
  const [email, setEmail] = useState('');
  const [subscribed, setSubscribed] = useState(false);

  const handleSubscribe = (e) => {
    e.preventDefault();
    if (email) {
      setSubscribed(true);
      setEmail('');
      setTimeout(() => setSubscribed(false), 3000);
    }
  };

  const footerContainerStyle = {
    background: 'linear-gradient(180deg, rgba(10, 17, 40, 0.9) 0%, rgba(5, 10, 25, 0.95) 100%)',
    backgroundImage: `linear-gradient(180deg, rgba(10, 17, 40, 0.9) 0%, rgba(5, 10, 25, 0.95) 100%),
                      radial-gradient(ellipse at 20% 50%, rgba(212, 175, 55, 0.05) 0%, transparent 50%),
                      radial-gradient(ellipse at 80% 80%, rgba(100, 150, 200, 0.03) 0%, transparent 50%)`,
    color: 'var(--text-white)',
    borderTop: '1px solid rgba(255, 255, 255, 0.08)',
    // marginTop: '80px',
  };

  const mainContentStyle = {
    maxWidth: '1400px',
    margin: '0 auto',
    padding: '60px 60px 40px',
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
    gap: '60px',
  };

  const logoSectionStyle = {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px',
  };

  const logoStyle = {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    marginBottom: '8px',
  };

  const logoTextStyle = {
    color: 'var(--accent-gold)',
    fontSize: '22px',
    fontWeight: '800',
    margin: 0,
    letterSpacing: '-0.5px',
  };

  const brandStatementStyle = {
    fontSize: '14px',
    color: 'rgba(255, 255, 255, 0.65)',
    lineHeight: '1.7',
    fontWeight: '300',
    letterSpacing: '0.3px',
    maxWidth: '300px',
  };

  const newsletterSectionStyle = {
    display: 'flex',
    flexDirection: 'column',
    gap: '16px',
  };

  const sectionTitleStyle = {
    fontSize: '14px',
    fontWeight: '700',
    color: 'var(--accent-gold)',
    margin: 0,
    letterSpacing: '0.5px',
    textTransform: 'uppercase',
  };

  const newsletterFormStyle = {
    display: 'flex',
    flexDirection: 'column',
    gap: '12px',
  };

  const inputStyle = {
    background: 'rgba(255, 255, 255, 0.08)',
    border: '1px solid rgba(255, 255, 255, 0.15)',
    borderRadius: '8px',
    padding: '12px 16px',
    color: 'var(--text-white)',
    fontSize: '14px',
    fontWeight: '400',
    transition: 'all 0.3s ease',
    outline: 'none',
    fontFamily: 'inherit',
  };

  const inputFocusStyle = {
    background: 'rgba(255, 255, 255, 0.12)',
    borderColor: 'rgba(212, 175, 55, 0.4)',
    boxShadow: '0 0 12px rgba(212, 175, 55, 0.1)',
  };

  const subscribeButtonStyle = {
    background: 'linear-gradient(135deg, var(--accent-gold), #c4a555)',
    color: 'var(--primary-maroon-dark)',
    padding: '12px 24px',
    border: 'none',
    borderRadius: '8px',
    fontWeight: '600',
    fontSize: '14px',
    cursor: 'pointer',
    transition: 'all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)',
    letterSpacing: '0.3px',
    boxShadow: '0 4px 12px rgba(212, 175, 55, 0.2)',
  };

  const subscribeButtonHoverStyle = {
    transform: 'translateY(-2px)',
    boxShadow: '0 8px 20px rgba(212, 175, 55, 0.3)',
  };

  const linkSectionStyle = {
    display: 'flex',
    flexDirection: 'column',
    gap: '12px',
  };

  const linkStyle = {
    color: 'rgba(255, 255, 255, 0.7)',
    textDecoration: 'none',
    fontSize: '14px',
    fontWeight: '400',
    transition: 'color 0.3s ease',
    letterSpacing: '0.2px',
  };

  const dividerStyle = {
    height: '1px',
    background: 'linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.1), transparent)',
    margin: '40px 0',
  };

  const copyrightSectionStyle = {
    maxWidth: '1400px',
    margin: '0 auto',
    padding: '20px 60px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    flexWrap: 'wrap',
    gap: '16px',
    borderTop: '1px solid rgba(255, 255, 255, 0.08)',
  };

  const copyrightTextStyle = {
    fontSize: '12px',
    color: 'rgba(255, 255, 255, 0.5)',
    fontWeight: '300',
    margin: 0,
  };

  const socialLinksStyle = {
    display: 'flex',
    gap: '20px',
  };

  const socialLinkStyle = {
    color: 'rgba(255, 255, 255, 0.5)',
    textDecoration: 'none',
    fontSize: '12px',
    transition: 'color 0.3s ease',
    fontWeight: '400',
  };

  const successMessageStyle = {
    fontSize: '12px',
    color: 'var(--accent-gold)',
    fontWeight: '500',
    margin: '8px 0 0 0',
  };

  return (
    <footer style={footerContainerStyle}>
      {/* Main Content */}
      <div style={mainContentStyle}>
        {/* Brand Section */}
        <div style={logoSectionStyle}>
          <div style={logoStyle}>
            <h3 style={logoTextStyle}>Artemis</h3>
          </div>
          <p style={brandStatementStyle}>
            Transforming enterprises through strategic consulting and next-generation innovation. Your vision, our expertise.
          </p>
        </div>

        {/* Newsletter Section */}
        <div style={newsletterSectionStyle}>
          <h4 style={sectionTitleStyle}>Stay Updated</h4>
          <p style={{ fontSize: '13px', color: 'rgba(255, 255, 255, 0.6)', margin: 0, fontWeight: '300' }}>
            Subscribe to our insights and industry trends
          </p>
          <form style={newsletterFormStyle} onSubmit={handleSubscribe}>
            <input
              type="email"
              placeholder="Enter your email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              style={inputStyle}
              onFocus={(e) => Object.assign(e.target.style, inputFocusStyle)}
              onBlur={(e) => {
                e.target.style.background = 'rgba(255, 255, 255, 0.08)';
                e.target.style.borderColor = 'rgba(255, 255, 255, 0.15)';
                e.target.style.boxShadow = 'none';
              }}
              required
            />
            <button
              type="submit"
              style={subscribeButtonStyle}
              onMouseEnter={(e) => Object.assign(e.target.style, subscribeButtonHoverStyle)}
              onMouseLeave={(e) => {
                e.target.style.transform = 'translateY(0)';
                e.target.style.boxShadow = '0 4px 12px rgba(212, 175, 55, 0.2)';
              }}
            >
              Subscribe
            </button>
            {subscribed && <p style={successMessageStyle}>✓ Thank you for subscribing!</p>}
          </form>
        </div>

        {/* Divider */}
        <div style={dividerStyle}></div>
      </div>

      {/* Copyright Section */}
      <div style={copyrightSectionStyle}>
        <p style={copyrightTextStyle}>
          © 2026 Artemis Consultants. All rights reserved.
        </p>
        <div style={socialLinksStyle}>
          <a
            href="#"
            style={socialLinkStyle}
            onMouseEnter={(e) => e.target.style.color = 'var(--accent-gold)'}
            onMouseLeave={(e) => e.target.style.color = 'rgba(255, 255, 255, 0.5)'}
          >
            Privacy
          </a>
          <a
            href="#"
            style={socialLinkStyle}
            onMouseEnter={(e) => e.target.style.color = 'var(--accent-gold)'}
            onMouseLeave={(e) => e.target.style.color = 'rgba(255, 255, 255, 0.5)'}
          >
            Terms
          </a>
          <a
            href="#"
            style={socialLinkStyle}
            onMouseEnter={(e) => e.target.style.color = 'var(--accent-gold)'}
            onMouseLeave={(e) => e.target.style.color = 'rgba(255, 255, 255, 0.5)'}
          >
            LinkedIn
          </a>
        </div>
      </div>
    </footer>
  );
};

export default Footer;
